-- Buscar Gilson em allowed_clients por nome
SELECT id, name, email, is_active FROM allowed_clients
WHERE name LIKE '%Gilson%' OR name LIKE '%gilson%';

-- Verificar se há algum allowed_client com email icloud similar
SELECT id, name, email, is_active FROM allowed_clients
WHERE email LIKE '%icloud%' OR email LIKE '%privaterelay%';
